from __future__ import annotations

from typing import Any, Dict, List

from .validator import _is_number, _json_equal

__all__ = [
    "evaluate_batch_rules",
    "InvalidBatchInputError",
    "InvalidBatchRuleError",
    "SUPPORTED_BATCH_TYPES",
